const fs = require('node:fs/promises');
const {chromium} = require('playwright-core');
(async () => {
  const chunks = [];
  for await (const chunk of process.stdin) chunks.push(chunk);
  const input = JSON.parse(Buffer.concat(chunks));
  const browser = await chromium.launch({executablePath:'/usr/bin/chromium'});
  try {
    const page = await browser.newPage();
    await page.setContent('<label>Order<select><option>ORD-1042</option><option>ORD-1043</option></select></label><button>Export</button><output></output>');
    await page.evaluate(() => {
      document.querySelector('button').onclick = () => {
        const id = document.querySelector('select').value;
        const quantity = {'ORD-1042':12,'ORD-1043':24}[id];
        document.querySelector('output').value = 'order_id,quantity\n'+id+','+quantity+'\n';
      };
    });
    await page.getByLabel('Order').selectOption(input.order_id);
    await page.getByText('Export',{exact:true}).click();
    await fs.writeFile(input.output_name,await page.locator('output').textContent(),{flag:'wx'});
  } finally { await browser.close(); }
})().catch(error=>{console.error(error.message);process.exitCode=1;});
